import java.math.BigInteger;
import java.util.Scanner;


public class Main {

    private static int weight;
    private static int itemMass;
    private static boolean[] arr=new boolean[100];
    static{
        for(int i=0;i<100;i++)
            arr[i]=false;
    }
    public boolean isBalanced(){
        boolean isBalance=false;
        long pod1=itemMass, pod2=0;

        while(true){
            if(pod1>pod2){
                long nextMass=getMass(pod1-pod2);
                //System.out.println("Pod1 wieght is higher: "+nextMass);
                if(nextMass!=0){
                    pod2+=nextMass;
                }
                else
                    break;
            }
            else if(pod1<pod2){
                long nextMass1=getMass(pod2-pod1);
                //System.out.println("Pod2 wieght is higher: "+nextMass1);
                if(nextMass1!=0){
                    pod1+=nextMass1;
                }
                else
                    break;
            }
            else{
                isBalance=true;
                break;
            }
        }
        return isBalance;
    }

    public long getMass(long mass){
        long result;
        int logBase=(int) (Math.log(mass)/Math.log(weight));
        //System.out.println("Mass is "+mass+" log is: "+logBase);
        //long sumTotal=((long) Math.pow(weight, logBase+1)-1)/(weight-1);

        BigInteger bi=new BigInteger(Integer.toString(weight));
        //System.out.println(bi.toString());
        bi=bi.pow(logBase+1);
        //System.out.println(bi.toString());
        bi=bi.subtract(new BigInteger(Integer.toString(1)));
        //System.out.println(bi.toString());
        bi=bi.divide(new BigInteger(Integer.toString(weight-1)));
        //System.out.println(bi.toString());
        long sumTotal=bi.longValue();

        //System.out.println("Mass is "+mass+" log is: "+logBase+" total mass is: "+sumTotal+" arr value: "+arr[logBase+1]+" "+arr[logBase]);
        if(mass>sumTotal && !arr[logBase+1]){
            result=(int) Math.pow(weight, logBase+1);
            arr[logBase+1]=true;
        }
        else if(mass<=sumTotal && !arr[logBase]){
            result=(int) Math.pow(weight, logBase);
            arr[logBase]=true;
        }
        else{
            result=0;
        }

        return result;  
    }

    public static void main(String[] args) {
        // TODO Auto-generated method stub
        Scanner sc=new Scanner(System.in);
        Main.weight=sc.nextInt();
        Main.itemMass=sc.nextInt();
        Main wb=new Main();

        if(wb.isBalanced())
            System.out.println("YES");
        else
            System.out.println("NO");
    }

}

